    printf("~A & 0xFF:    %u (0x%02X)\n", (~a) & 0xFF, (~a) & 0xFF);
}

int main(void) {
    int choice;
    do {
        printf("\n================ TRUTH TABLE GENERATOR ================\n");
        printf("1. Single 2-Variable Logic Gate (AND, OR, XOR, etc.)\n");
