                if (scanf("%d", &E) != 1 || E < 0) { clear_input(); break; }
                printf("Enter %d edges as 'u v' (1-based indices):\n", E);
                for (int e = 0; e < E; e++) {
                    int u, v;
                    if (scanf("%d %d", &u, &v) == 2) {
                        if (u >= 1 && u <= V && v >= 1 && v <= V && u != v) {
