                int odd_count = 0;
                for (int i = 0; i < V; i++) {
                    int deg = 0;
                    for (int j = 0; j < V; j++) deg += adj[i][j];
                    if (deg % 2 != 0) odd_count++;
                }
                printf("\nEulerian Feasibility Analysis:\n");
                printf("Vertices with ODD degree: %d\n", odd_count);
                if (odd_count == 0) {
