                }
                if (iso == 0) printf("No isolated vertices.\n");
                if (pend == 0) printf("No pendent vertices.\n");
                break;
            }
            case 0:
                printf("Exiting Vertex Degrees Analyzer.\n");
                break;
            default:
                printf("Invalid selection.\n");
        }
    } while (choice != 0);

    return 0;
}

