            double (*f)(double, double) = (choice == 1) ? ode1 : ode2;
            double (*ex)(double) = (choice == 1) ? exact1 : exact2;
            double y0 = (choice == 1) ? 1.0 : 0.5;

            double h = 0.1, target_x = 1.0;
