                    printf("Probability P(%.2f <= X <= %.2f) = %.6f (%.2f%%)\n", a, b, prob, prob * 100.0);
                } else { clear_input(); }
                break;
            }
            case 4:
                printf("\n--- Empirical Rule (68-95-99.7%% Rule) ---\n");
                printf("  68.27%% Interval [mu - 1*s, mu + 1*s]: [%.4f, %.4f]\n", mu - sigma, mu + sigma);
