                    printf("Predicted y_hat at x = %.4f: %.6f\n", qx, m * qx + c);
                } else { clear_input(); }
                break;
            }
            case 0:
                printf("Exiting Linear Regression.\n");
                break;
            default:
                printf("Invalid selection.\n");
        }
    } while (choice != 0);

    return 0;
